lib={}
for tn,tv in tf.items():
    for i in range(3):
        for j in range(3):
            if i+j<=2:
                lib[f'x^{i}v^{j}*{tn}']=(x**i)*(v**j)*tv
y=dv_dt
sel=[]
def err(names):
    A=np.column_stack([lib[n] for n in names]); c,_,_,_=np.linalg.lstsq(A,y,rcond=None)
    return np.mean((y-A@c)**2)/np.var(y), c
for step in range(10):
